
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbe_mol_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbe_mol", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.337621332549088e+00, -4.256413642265678e+00, -4.142752118486479e+00, -3.985573848552745e+00, -3.771963241885719e+00, -3.488831315602458e+00, -3.126767238823697e+00, -2.686658361036838e+00, -2.186941131502860e+00, -1.659338383985779e+00, -1.119794476763100e+00, -7.171488690975429e-01, -6.052695948938966e-01, -5.080669286468351e-01, -3.795705442873890e-01, -2.507203589294877e-01, -1.361114490338835e-01, -4.970005281321701e-02, -1.081387392565488e-02, -1.216204986887693e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


